const row = $('Validate & Prepare Sign').item.json;
// Base the down payment on the proposal's scope of work (its line items + total),
// since that's the agreed-upon price breakdown — fall back to the contract's flat
// total only if this contract has no linked proposal.
const scopeTotal = row.proposalTotalAmount != null ? Number(row.proposalTotalAmount) : Number(row.totalAmount) || 0;
const scopeLineItems = Array.isArray(row.proposalLineItems) ? row.proposalLineItems : [];
const amount = Math.round(scopeTotal * 0.30 * 100) / 100;
const balance = Math.round((scopeTotal - amount) * 100) / 100;
const lineItems = [{ product: 'Down Payment (30%)', qty: 1, unit_price: amount, discount: 0, tax: 0, total: amount }];
const money = (n) => n.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const customerNotes = `Down payment (30% of $${money(scopeTotal)} — ${row.dealName || 'this job'}) — Balance due on completion: $${money(balance)}`;
return [{ json: { amount, lineItemsJson: JSON.stringify(lineItems), scopeLineItemsJson: JSON.stringify(scopeLineItems), scopeTotal, customerNotes } }];

