WITH existing AS (
  SELECT id FROM invoices WHERE opportunity_id = $1 AND invoice_type = 'down_payment' LIMIT 1
),
inserted AS (
  INSERT INTO invoices (opportunity_id, contact_id, amount, tax, discount, total, line_items, issue_date, due_date, invoice_type, invoice_number, customer_notes)
  SELECT $1, $2, $3, 0, 0, $3, $4::jsonb, CURRENT_DATE, CURRENT_DATE + 7, 'down_payment', '', $5
  WHERE NOT EXISTS (SELECT 1 FROM existing)
  RETURNING id
)
SELECT id FROM inserted UNION ALL SELECT id FROM existing LIMIT 1;

