if (row.cosigned_at) throw new Error('This contract has already been countersigned.');

// The countersignature represents the deal's assigned owner (matches
// the {{owner_name}} merge token already printed in the document body,
// e.g. "Apex Roofing Representative: Juan Smith") — always attributed
// to them even when an admin is the one physically clicking Countersign
// on their behalf, so the audit trail never disagrees with the document
// text. Falls back to the acting admin only if the deal somehow has no
// assigned owner.
const cosignedBy = row.assigned_user || requester.id;

return [{ json: { contractId: row.id, cosignedBy, ownerFieldId, signatureData, fieldValues: JSON.stringify(fieldValues || {}) } }];

parameters.query:
UPDATE contracts SET cosign_signature_data = $1, cosigned_by = $2, cosigned_at = now(),
  field_values = (jsonb_set(COALESCE(field_values, '{}'::jsonb), ARRAY[$3], to_jsonb($1::text)) || $5::jsonb)
WHERE id = $4 AND cosigned_at IS NULL RETURNING id;

